      "type": "integer",
      "x-since": 2
    },
    "generated_at": {
      "description": "Generation timestamp supplied by the producer, retained verbatim.",
      "title": "Generated At",
      "type": "string",
      "x-since": 1
    },
    "generator": {
      "$ref": "#/$defs/Generator",
      "description": "Application that produced this snapshot.",
      "x-since": 1
    }
  },
  "required": [
    "format",
    "format_version",
    "generator",
    "generated_at",
    "content_sha256",
    "content"
  ],
  "title": "Document",
  "type": "object"
}

