query contract.pretty:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Catabolic query input shape v1",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "version": {
      "const": 1
    },
    "mode": {
      "enum": [
        "selection",
        "rows",
        "document"
      ]
    },
    "entity": {
      "enum": [
        "item_id",
        "file_id",
        "association_id"
      ]
    },
    "max_ids": {
      "type": "integer",
      "minimum": 1,
      "maximum": 100000
    },
    "timeout_ms": {
      "type": "integer",
      "minimum": 1,
      "maximum": 60000
    },
    "selection": {
      "type": "object",
      "required": [
        "language",
        "query"
      ],
      "additionalProperties": false,
      "properties": {
        "language": {
          "enum": [
            "sql",
            "graphql"
          ]
        },
        "query": {
          "type": "string",
          "minLength": 1
        },
        "profile": {
          "type": "string",
          "minLength": 1
        },
        "params": {
          "type": "object"
        },
        "variables": {
          "type": "object"
        },
        "max_ids": {
          "type": "integer",
          "minimum": 1,
          "maximum": 100000
        },
        "page_size": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9999
        },
        "timeout_ms": {
          "type": "integer",
          "minimum": 1,
          "maximum": 60000
        }
      }
    },
    "combine": {
      "enum": [
        "union",
        "intersection",
        "difference"
      ]
    },
    "queries": {
      "type": "array",
      "minItems": 2,
      "maxItems": 16,
      "items": {
        "type": "string",
        "minLength": 1
      }
    }
  },
  "oneOf": [
    {
      "required": [
        "selection"
      ],
      "not": {
        "anyOf": [
          {
            "required": [
              "combine"
            ]
          },
          {
            "required": [
              "queries"
            ]
          }
        ]
      }
    },
    {
      "required": [
        "combine",
        "queries"
      ],
      "not": {
        "required": [
          "selection"
        ]
      }
    }
  ],
  "$comment": "Shape validation is not selection completeness. SQL/GraphQL language contracts, compatible modes, profiles, revision references, execution budgets and returned IDs are validated by the query owner."
}

